import React from 'react';
import { Doughnut } from 'react-chartjs-2';

const Charts = ({ tasks }) => {
  const data = {
    labels: ['Urgent & Important', 'Not Urgent & Important', 'Urgent & Not Important', 'Not Urgent & Not Important'],
    datasets: [
      {
        data: [
          tasks.filter((task) => task.quadrant === 'Urgent-Important').length,
          tasks.filter((task) => task.quadrant === 'NotUrgent-Important').length,
          tasks.filter((task) => task.quadrant === 'Urgent-NotImportant').length,
          tasks.filter((task) => task.quadrant === 'NotUrgent-NotImportant').length,
        ],
        backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0'],
      },
    ],
  };

  return <Doughnut data={data} />;
};

export default Charts;
